-- Frozen copy of the real schema created by FuturesMarketStore (server/src/features/kraken-futures/futures-market-store.ts),
-- generated by running that store; used by test_capture_minimal_read so plans are checked on the real tables (STRICT, column order, indexes).
CREATE TABLE paper_futures_market_migrations (
        version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_instrument_versions (
        metadata_hash TEXT PRIMARY KEY, instrument_id TEXT NOT NULL, retrieved_at INTEGER NOT NULL,
        payload_json TEXT NOT NULL, raw_json TEXT NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_market_events (
        event_id TEXT PRIMARY KEY, feed TEXT NOT NULL, product_id TEXT NOT NULL,
        epoch INTEGER NOT NULL, seq INTEGER NOT NULL, event_time INTEGER NOT NULL,
        received_at INTEGER NOT NULL, persisted_at INTEGER NOT NULL, uid TEXT,
        raw_json TEXT NOT NULL, normalized_json TEXT NOT NULL, content_hash TEXT NOT NULL
      ) STRICT;
CREATE UNIQUE INDEX paper_futures_market_trade_uid
        ON paper_futures_market_events(feed, product_id, uid) WHERE uid IS NOT NULL;
CREATE INDEX paper_futures_market_received
        ON paper_futures_market_events(product_id, received_at, seq);
CREATE TABLE paper_futures_book_snapshots (
        event_id TEXT PRIMARY KEY REFERENCES paper_futures_market_events(event_id),
        product_id TEXT NOT NULL, epoch INTEGER NOT NULL, seq INTEGER NOT NULL,
        event_time INTEGER NOT NULL, received_at INTEGER NOT NULL, bids_json TEXT NOT NULL, asks_json TEXT NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_ticker_snapshots (
        event_id TEXT PRIMARY KEY REFERENCES paper_futures_market_events(event_id),
        product_id TEXT NOT NULL, epoch INTEGER NOT NULL, seq INTEGER NOT NULL,
        event_time INTEGER NOT NULL, received_at INTEGER NOT NULL, payload_json TEXT NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_data_gaps (
        gap_id TEXT PRIMARY KEY, feed TEXT NOT NULL, product_id TEXT NOT NULL,
        epoch INTEGER NOT NULL, expected_seq INTEGER, actual_seq INTEGER,
        detected_at INTEGER NOT NULL, reason TEXT NOT NULL, policy_version TEXT NOT NULL
      ) STRICT;
CREATE INDEX paper_futures_data_gaps_detected_at
        ON paper_futures_data_gaps(detected_at);
CREATE TABLE paper_futures_candle_revisions (
        candle_id TEXT NOT NULL, interval_ms INTEGER NOT NULL, bucket_start INTEGER NOT NULL,
        revision INTEGER NOT NULL, known_at INTEGER NOT NULL, close_at INTEGER,
        is_closed INTEGER NOT NULL, coverage TEXT NOT NULL, open_price TEXT NOT NULL,
        high_price TEXT NOT NULL, low_price TEXT NOT NULL, close_price TEXT NOT NULL,
        volume_btc TEXT NOT NULL, trade_count INTEGER NOT NULL, source_hash TEXT NOT NULL,
        PRIMARY KEY(candle_id, revision)
      ) STRICT;
CREATE INDEX paper_futures_candle_revisions_bucket
        ON paper_futures_candle_revisions(interval_ms, bucket_start);
CREATE TABLE paper_futures_market_quality_policies (
        policy_version TEXT PRIMARY KEY, recorded_at INTEGER NOT NULL,
        payload_json TEXT NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_funding_responses(
        sha256 TEXT PRIMARY KEY, received_at INTEGER NOT NULL, server_time TEXT NOT NULL, raw_response TEXT NOT NULL
      ) STRICT;
CREATE TABLE paper_futures_funding_periods(
        response_sha256 TEXT NOT NULL REFERENCES paper_futures_funding_responses(sha256),
        start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL, funding_rate TEXT NOT NULL,
        known_at INTEGER NOT NULL, unit TEXT NOT NULL, product_id TEXT NOT NULL DEFAULT 'PF_XBTUSD', PRIMARY KEY(response_sha256,start_ms)
      ) STRICT;
CREATE TRIGGER paper_futures_funding_responses_no_update
        BEFORE UPDATE ON paper_futures_funding_responses BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_funding_responses_no_delete
        BEFORE DELETE ON paper_futures_funding_responses BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_funding_periods_no_update
        BEFORE UPDATE ON paper_futures_funding_periods BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_funding_periods_no_delete
        BEFORE DELETE ON paper_futures_funding_periods BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_market_quality_policies_no_update
        BEFORE UPDATE ON paper_futures_market_quality_policies BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_market_quality_policies_no_delete
        BEFORE DELETE ON paper_futures_market_quality_policies BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_market_events_no_update
        BEFORE UPDATE ON paper_futures_market_events BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_market_events_no_delete
        BEFORE DELETE ON paper_futures_market_events BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_instrument_versions_no_update
        BEFORE UPDATE ON paper_futures_instrument_versions BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_instrument_versions_no_delete
        BEFORE DELETE ON paper_futures_instrument_versions BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_book_snapshots_no_update
        BEFORE UPDATE ON paper_futures_book_snapshots BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_book_snapshots_no_delete
        BEFORE DELETE ON paper_futures_book_snapshots BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_ticker_snapshots_no_update
        BEFORE UPDATE ON paper_futures_ticker_snapshots BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_ticker_snapshots_no_delete
        BEFORE DELETE ON paper_futures_ticker_snapshots BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_data_gaps_no_update
        BEFORE UPDATE ON paper_futures_data_gaps BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_data_gaps_no_delete
        BEFORE DELETE ON paper_futures_data_gaps BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_candle_revisions_no_update
        BEFORE UPDATE ON paper_futures_candle_revisions BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_candle_revisions_no_delete
        BEFORE DELETE ON paper_futures_candle_revisions BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TABLE "paper_futures_official_candle_responses"(
            product_id TEXT NOT NULL, sha256 TEXT NOT NULL, interval_ms INTEGER NOT NULL,
            from_ms INTEGER NOT NULL, to_ms INTEGER NOT NULL, received_at INTEGER NOT NULL,
            raw_response TEXT NOT NULL, PRIMARY KEY(product_id, sha256)
          ) STRICT;
CREATE TABLE "paper_futures_official_candles"(
            product_id TEXT NOT NULL, interval_ms INTEGER NOT NULL, bucket_start INTEGER NOT NULL,
            revision_hash TEXT NOT NULL, known_at INTEGER NOT NULL, open_price TEXT NOT NULL,
            high_price TEXT NOT NULL, low_price TEXT NOT NULL, close_price TEXT NOT NULL,
            volume_btc TEXT NOT NULL, response_sha256 TEXT NOT NULL,
            PRIMARY KEY(product_id, interval_ms, bucket_start, revision_hash),
            FOREIGN KEY(product_id, response_sha256) REFERENCES "paper_futures_official_candle_responses"(product_id, sha256)
          ) STRICT;
CREATE TRIGGER paper_futures_official_candle_responses_no_update
            BEFORE UPDATE ON paper_futures_official_candle_responses BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_official_candle_responses_no_delete
            BEFORE DELETE ON paper_futures_official_candle_responses BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_official_candles_no_update
            BEFORE UPDATE ON paper_futures_official_candles BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_official_candles_no_delete
            BEFORE DELETE ON paper_futures_official_candles BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TABLE paper_futures_analytics_responses(
        product_id TEXT NOT NULL, sha256 TEXT NOT NULL, metric TEXT NOT NULL,
        interval_ms INTEGER NOT NULL, from_ms INTEGER NOT NULL, received_at INTEGER NOT NULL,
        raw_response TEXT NOT NULL, PRIMARY KEY(product_id, sha256)
      ) STRICT;
CREATE TABLE paper_futures_analytics_points(
        product_id TEXT NOT NULL, metric TEXT NOT NULL, interval_ms INTEGER NOT NULL,
        bucket_start INTEGER NOT NULL, revision_hash TEXT NOT NULL, known_at INTEGER NOT NULL,
        values_json TEXT NOT NULL, response_sha256 TEXT NOT NULL,
        PRIMARY KEY(product_id, metric, interval_ms, bucket_start, revision_hash),
        FOREIGN KEY(product_id, response_sha256) REFERENCES paper_futures_analytics_responses(product_id, sha256)
      ) STRICT;
CREATE TRIGGER paper_futures_analytics_responses_no_update
        BEFORE UPDATE ON paper_futures_analytics_responses BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_analytics_responses_no_delete
        BEFORE DELETE ON paper_futures_analytics_responses BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_analytics_points_no_update
        BEFORE UPDATE ON paper_futures_analytics_points BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TRIGGER paper_futures_analytics_points_no_delete
        BEFORE DELETE ON paper_futures_analytics_points BEGIN SELECT RAISE(ABORT, 'market evidence is immutable'); END;
CREATE TABLE paper_futures_funding_polls(
        product_id TEXT NOT NULL, started_at INTEGER NOT NULL, purpose TEXT NOT NULL,
        scheduled_at INTEGER NOT NULL, finished_at INTEGER NOT NULL, outcome TEXT NOT NULL,
        http_status INTEGER, detail TEXT, response_sha256 TEXT,
        extract_text TEXT, extract_sha256 TEXT, extract_periods INTEGER,
        PRIMARY KEY(product_id, started_at, purpose)
      ) STRICT;
CREATE TABLE paper_futures_funding_sightings(
        product_id TEXT NOT NULL, start_ms INTEGER NOT NULL, received_at INTEGER NOT NULL,
        funding_rate TEXT NOT NULL, end_ms INTEGER NOT NULL, server_time TEXT NOT NULL,
        response_sha256 TEXT NOT NULL,
        PRIMARY KEY(product_id, start_ms, received_at)
      ) STRICT;
CREATE TRIGGER paper_futures_funding_polls_no_update
        BEFORE UPDATE ON paper_futures_funding_polls BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_funding_polls_no_delete
        BEFORE DELETE ON paper_futures_funding_polls BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
CREATE TRIGGER paper_futures_funding_sightings_no_update
        BEFORE UPDATE ON paper_futures_funding_sightings BEGIN SELECT RAISE(ABORT, 'funding evidence is immutable'); END;
